    getDaysUntilExecution(executionAt) {
        const executionMs = executionAt > 1e12 ? executionAt : executionAt * 1000;
        return Math.max(0, Math.ceil((executionMs - Date.now()) / 86400000));
    }
    applyPendingMessage() {
        const template = salla.lang.get('pages.profile.delete_account_pending');
        this.deleteAccountPending =
            this.deletePendingDays != null
                ? template.replace(/:days/g, String(salla.helpers.number(this.deletePendingDays)))
                : template;
    }
    async fetchDeleteRequestStatus() {
        try {
            const response = await salla.profile.getDeleteRequest();
            const request = response?.data ?? null;
            const dataRequest = request?.data_request || request;
            const status = dataRequest?.status;
            this.isDeletePending = status === 'pending';
            const executionAt = dataRequest?.execution_at;
            this.deletePendingDays =
                executionAt != null && !Number.isNaN(Number(executionAt))
                    ? this.getDaysUntilExecution(Number(executionAt))
                    : null;
            this.applyPendingMessage();
        }
        catch {
            // Preserve current pending state. After OTP success we set isDeletePending
            // optimistically; a transient GET failure must not flip the UI back to
            // "Delete account" for a request that is already queued.
        }
    }
